page Counter "/" {
  state count = 0
  computed double = count * 2
  fn inc() {
    if count < 10 {
      count++
    }
  }
  fn dec() {
    if count > 0 {
      count--
    }
  }

  column gap=4 align=center {
    title "Contador"
    row gap=2 {
      button "-" disabled=(count <= 0) -> dec()
      text count bold
      button "+" primary disabled=(count >= 10) -> inc()
    }
    button "Reset" danger small -> count = 0
    text `El doble es ${double}` muted
    if count > 5 {
      text "¡Más de 5!"
    }
  }
}

